{{ config(materialized='incremental') }}
/* GENERATED by gen_hcon_vault.py -- models are generated.
   SAT_INSTRUMENT_DEFINITION
   anchor      : HUB_PAYMENT_INSTRUMENT   (kind: hub, origin: map.anchor)
   track       : ratified
   history     : SCD2
   feeders     : 1 emitted of 3 (one per source view AND run)
   runs        : 1 -- opus_health_legacy_v4
   payload     : 4 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_PAYMENT_INSTRUMENT_HK
   hashdiff    : SAT_INSTRUMENT_DEFINITION_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_PAYMENT_INSTRUMENT|' || (HUB_PAYMENT_INSTRUMENT_BK__CHEQUE_NO))) as HUB_PAYMENT_INSTRUMENT_HK
        , cast(null as varchar) as INSTRUMENT_TYPE
        , cast(null as varchar) as BRANCH_NAME
        , DEBIT_CARD_NO as CARD_NUMBER_MASKED
        , cast(null as varchar) as ACCOUNT_HOLDER_NAME
        , 'BJAZ_HM_HCM_EXTRACT' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcm_extract') }}
    where (nullif(trim(CHEQUE_NO),'')) is not null
),

resolved as (
    select
        HUB_PAYMENT_INSTRUMENT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then INSTRUMENT_TYPE end) as INSTRUMENT_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BRANCH_NAME end) as BRANCH_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CARD_NUMBER_MASKED end) as CARD_NUMBER_MASKED,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ACCOUNT_HOLDER_NAME end) as ACCOUNT_HOLDER_NAME,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PAYMENT_INSTRUMENT_HK
),

hashed as (
    select
        *,
        case when INSTRUMENT_TYPE is not null or BRANCH_NAME is not null or CARD_NUMBER_MASKED is not null or ACCOUNT_HOLDER_NAME is not null
                     then md5(upper(coalesce(cast(INSTRUMENT_TYPE as varchar), '') || '|' || coalesce(cast(BRANCH_NAME as varchar), '') || '|' || coalesce(cast(CARD_NUMBER_MASKED as varchar), '') || '|' || coalesce(cast(ACCOUNT_HOLDER_NAME as varchar), '')))
                end as SAT_INSTRUMENT_DEFINITION_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PAYMENT_INSTRUMENT_HK is not null
  and SAT_INSTRUMENT_DEFINITION_HASHDIFF is not null
